const DEPTH_KEY='zafa-btcusdt-usdm-depth-v1',DEPTH_MS=1800000;
let hipDepthDB=null,hipDepthOpening=null,hipDepthPending=[],hipDepthStatus='local archive waiting';
function openHipDepth(){if(hipDepthDB)return Promise.resolve(hipDepthDB);if(hipDepthOpening)return hipDepthOpening;hipDepthOpening=new Promise(resolve=>{if(typeof indexedDB==='undefined'){hipDepthStatus='memory only';resolve(null);return}try{const req=indexedDB.open('zafa-hip-depth-v1',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('samples'))req.result.createObjectStore('samples',{keyPath:['market','t']})};req.onsuccess=()=>{hipDepthDB=req.result;hipDepthDB.onversionchange=()=>{hipDepthDB?.close();hipDepthDB=null;hipDepthOpening=null};hipDepthStatus='local IndexedDB';resolve(hipDepthDB)};req.onerror=()=>{hipDepthStatus='memory only · storage unavailable';resolve(null)}}catch{hipDepthStatus='memory only · storage unavailable';resolve(null)}});return hipDepthOpening}
function queueHipDepth(s){if(replaySession||!isHL())return;hipDepthPending.push({market:symbol,t:s.t,p:s.p,bins:[...s.bins].map(([p,v])=>[p,v.buy,v.sell])});if(hipDepthPending.length>240)hipDepthPending.splice(0,hipDepthPending.length-240);if(hipDepthPending.length>=10)void flushHipDepth()}
async function flushHipDepth(){if(!hipDepthPending.length)return;const db=await openHipDepth();if(!db)return;const batch=hipDepthPending.splice(0);if(!batch.length)return;try{const tx=db.transaction('samples','readwrite'),st=tx.objectStore('samples'),cut=Date.now()-DEPTH_MS;for(const m of new Set(batch.map(s=>s.market)))st.delete(IDBKeyRange.bound([m,0],[m,cut],false,true));for(const s of batch)if(s.t>=cut)st.put(s);tx.onabort=()=>{hipDepthStatus='local storage write failed';hipDepthPending=batch.concat(hipDepthPending).slice(-240)}}catch{hipDepthStatus='local storage write failed'}}
async function loadHipDepth(g,market){const db=await openHipDepth();if(!db||g!==epoch||market!==symbol||replaySession)return;try{const req=db.transaction('samples','readonly').objectStore('samples').getAll(IDBKeyRange.bound([market,Date.now()-DEPTH_MS],[market,Date.now()+5000]));req.onsuccess=()=>{if(g!==epoch||market!==symbol||replaySession)return;const m=new Map(req.result.filter(s=>Array.isArray(s.bins)).map(s=>[s.t,{t:s.t,p:s.p??null,deep:false,bins:new Map(s.bins.map(([p,buy,sell])=>[p,{buy,sell}]))}]));for(const s of depthHistory)m.set(s.t,s);depthHistory=[...m.values()].filter(s=>s.t>=Date.now()-DEPTH_MS).sort((a,b)=>a.t-b.t).slice(-1801);dirty=true;mainChart.queue()};req.onerror=()=>{hipDepthStatus='local archive read failed'}}catch{hipDepthStatus='local archive read failed'}}
let depthDB=null,depthDBPending=[],depthDBOpening=false;
function restoreDepth(){try{const raw=JSON.parse(localStorage.getItem(DEPTH_KEY)||'[]'),now=Date.now();return raw.filter(s=>Array.isArray(s)&&Number.isFinite(s[0])&&s[0]>=now-DEPTH_MS&&s[0]<=now+5000&&Array.isArray(s[1])).slice(-1801).map(s=>({t:s[0],bins:new Map(s[1].filter(v=>v.length===3&&v.every(Number.isFinite)).map(([p,buy,sell])=>[p,{buy,sell}])),p:null,deep:true})).sort((a,b)=>a.t-b.t)}catch{return []}}
function saveDepth(){if(replaySession)return;if(isHL()){flushHipDepth();return}flushDepthDB();try{const rows=depthHistory.filter(s=>Date.now()-s.t<=DEPTH_MS);let out=[],size=2;for(let i=rows.length-1;i>=0;i--){const s=rows[i],row=JSON.stringify([s.t,[...s.bins].map(([p,v])=>[p,Number(v.buy.toFixed(6)),Number(v.sell.toFixed(6))])]);if(size+row.length+1>1800000)break;out.push(row);size+=row.length+1}localStorage.setItem(DEPTH_KEY,'['+out.reverse().join(',')+']')}catch{}}
function queueDepthSave(s){if(isHL())return;if(typeof indexedDB==='undefined')return;depthDBPending.push([s.t,[...s.bins].map(([p,v])=>[p,v.buy,v.sell])]);if(depthDBPending.length>120)depthDBPending.shift();if(depthDBPending.length>=10)flushDepthDB()}
function flushDepthDB(){if(!depthDB||!depthDBPending.length)return;const batch=depthDBPending.splice(0);try{const tx=depthDB.transaction('snapshots','readwrite'),st=tx.objectStore('snapshots');for(const [t,bins]of batch)st.put({t,bins});st.delete(IDBKeyRange.upperBound(Date.now()-DEPTH_MS,true));tx.onabort=()=>{depthDBPending=batch.concat(depthDBPending).slice(-120)}}catch{depthDBPending=batch.concat(depthDBPending).slice(-120)}}
function openDepthDB(){if(typeof indexedDB==='undefined'||depthDB||depthDBOpening)return;depthDBOpening=true;try{const req=indexedDB.open('zafa-btc-usdm-depth-v1',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('snapshots'))db.createObjectStore('snapshots',{keyPath:'t'})};req.onerror=()=>{depthDBOpening=false};req.onsuccess=()=>{depthDBOpening=false;depthDB=req.result;depthDB.onversionchange=()=>{depthDB?.close();depthDB=null;depthDBOpening=false};readDepthDB();flushDepthDB()}}catch{depthDBOpening=false}}
