const fpDelay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function fpRequest(path){if(Date.now()<fpHistoryCooldown)throw Object.assign(Error('API cooldown'),{status:429});let error;for(const host of [fpHost,...fpHosts.filter(x=>x!==fpHost)]){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),10000);try{const res=await fetch(host+path,{signal:ctl.signal,cache:'no-store'});if(!res.ok){const e=Error('HTTP '+res.status);e.status=res.status;if(res.status===429||res.status===418){fpHistoryCooldown=Date.now()+Math.max(60000,Number(res.headers?.get('Retry-After')||0)*1000);throw e}throw e}const data=await res.json();if(!Array.isArray(data))throw Error('Invalid Binance response');fpHost=host;return data}catch(e){error=e;if(e.status===429||e.status===418)throw e}finally{clearTimeout(timer)}}throw error||Error('Binance unavailable')}
function parseFpAggregate(a){const x=window.ZafaMarketData.trade({venue:'binance',market:'BTCUSDT',price:a.p,quantity:a.q,time:a.T,id:a.a,side:typeof a.m==='boolean'?(a.m?'sell':'buy'):null}),id=Number(a.a),first=Number(a.f),last=Number(a.l);if(!x||!Number.isSafeInteger(id)||!Number.isSafeInteger(first)||!Number.isSafeInteger(last)||last<first)throw Error('Invalid aggregate');return {p:x.p/TICK,q:x.q,t:x.t,id,side:x.side,count:1}}
function validateFpMinute(rows,k){if(!Number.isFinite(k?.vol)||!Number.isFinite(k?.buy))throw Error('Missing candle volume');let total=0,buy=0,count=0;for(const t of rows){total+=t.q;if(t.side==='buy')buy+=t.q;count+=t.count}const close=(a,b)=>Math.abs(a-b)<=Math.max(1e-7,Math.abs(b)*1e-9);if(!close(total,k.vol)||!close(buy,k.buy))throw Error('Volume check failed');return {rows,countOK:true}}
async function fetchFpMinute(t,g){let k=history.find(x=>x.t===t);if(!k||!Number.isFinite(k.vol)||!Number.isFinite(k.buy)){const ks=await fpRequest('/fapi/v1/klines?symbol=BTCUSDT&interval=1m&startTime='+t+'&endTime='+(t+59999)+'&limit=1');k=parseHistory(ks).find(x=>x.t===t)}if(g!==epoch)throw Error('Connection changed');const rows=[];let next=null,complete=false,lastId=null;
for(let page=0;page<80;page++){if(g!==epoch)throw Error('Connection changed');const path='/fapi/v1/aggTrades?symbol=BTCUSDT&limit=1000&'+(next===null?'startTime='+t+'&endTime='+(t+59999):'fromId='+next);const data=await fpRequest(path);if(g!==epoch)throw Error('Connection changed');for(const v of data){const a=parseFpAggregate(v);if(lastId!==null&&a.id!==lastId+1)throw Error('Aggregate sequence gap');lastId=a.id;if(a.t<t)throw Error('Unexpected time');if(a.t>=t+60000){complete=true;break}rows.push(a)}if(complete||data.length<1000){complete=true;break}next=lastId+1;await fpDelay(1000)}
if(!complete)throw Error('Minute exceeds page limit');return validateFpMinute(rows,k)}
function fpHistoryMinutes(list){if(period>30){fpHistoryError='Higher timeframe: observed trades only';return []}const cutoff=Math.floor((trades.at(-1)?.t??0)/60000)*60000-120000;const times=new Set();for(const b of list){if(!b.history&&!b.partial&&!b.gap&&b.raw?.length)continue;for(let t=b.time;t<b.time+period*60000;t+=60000)if(t<=cutoff&&!fpHistorical.has(t))times.add(t)}return [...times].sort((a,b)=>b-a)}
async function loadFpHistory(list,g=epoch){if(replaySession){fpHistoryError='Replay: recorded trades only';return}if(isHL()){fpHistoryError='HIP-3: observed trades only';mainChart.queue();return}if(g!==epoch||fpHistoryBusy||!widgetOpen.foot)return;if(fp.min||fp.max){fpHistoryError='Historical aggregates disabled by per-trade filters';mainChart.queue();return}if(Date.now()<fpHistoryCooldown){fpHistoryError='API rate limit · retry later';mainChart.queue();return}const targets=fpHistoryMinutes(list).slice(0,60);if(!targets.length)return;fpHistoryBusy=true;fpHistoryDone=0;fpHistoryTarget=targets.length;fpHistoryError='';mainChart.queue();try{for(const t of targets){if(g!==epoch||!widgetOpen.foot)break;try{const item=await fetchFpMinute(t,g);if(g!==epoch)return;fpHistorical.set(t,item);fpHistoryRevision++;if(fpHistorical.size>180)fpHistorical.delete(fpHistorical.keys().next().value);fpHistoryDone++;mainChart.queue()}catch(e){fpHistoryError=e.message||'History unavailable';if(e.status===429||e.status===418||/Connection changed|HTTP|fetch|network/i.test(fpHistoryError))break}await fpDelay(1000)}}finally{if(g===epoch){fpHistoryBusy=false;mainChart.queue()}}}
