function mergeOlderTrades(rows){if(!trades.length)return 0;const boundary=trades[0],map=new Map();for(const t of rows)if(t&&t.id<boundary.id&&t.t<=boundary.t)map.set(t.id,t);
const accepted=[];let id=boundary.id-1,ts=boundary.t;while(map.has(id)){const t=map.get(id);if(t.t>ts)break;accepted.push(t);ts=t.t;id--}if(!accepted.length)return 0;accepted.reverse();trades=accepted.concat(trades);rebuild();return accepted.length}
