async function fetchTradePage(host,from){if(Date.now()<fpHistoryCooldown)throw Object.assign(Error('API cooldown'),{status:429});const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),8000);try{const response=await fetch(host+'/fapi/v1/aggTrades?symbol=BTCUSDT&limit=1000&fromId='+from,{signal:ctl.signal,cache:'no-store'});if(!response.ok){const e=Error('HTTP '+response.status);e.status=response.status;if(e.status===429||e.status===418)fpHistoryCooldown=Date.now()+Math.max(60000,Number(response.headers?.get('Retry-After')||0)*1000);throw e}const rows=await response.json();if(!Array.isArray(rows))throw Error('Invalid trade history');return rows.map(parseHistoricalTrade).filter(Boolean)}finally{clearTimeout(timer)}}
async function recentTrades(){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),8000);try{const res=await fetch('https://fapi.binance.com/fapi/v1/aggTrades?symbol=BTCUSDT&limit=1000',{signal:ctl.signal,cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);const data=await res.json();if(!Array.isArray(data))throw Error('Invalid recent trades');return data.map(parseHistoricalTrade).filter(Boolean)}finally{clearTimeout(timer)}}
