async function loadOlderTrades(g,pages=80,targetMinutes=30){if(replaySession||isHL())return;if(g!==epoch||tradeLoading||!trades.length)return;tradeLoading=true;$('moreTrades').disabled=true;let total=0,host=null,error='';try{
let edge=trades[0].id;
for(const candidate of tradeHosts){if(g!==epoch)return;try{const rows=await fetchTradePage(candidate,Math.max(0,edge-1000));if(g!==epoch)return;const n=mergeOlderTrades(rows);if(n){total+=n;host=candidate;break}error='No contiguous historical trades'}catch(e){error=e.message||'Request failed';if(e.status===429||e.status===418)throw e}}
if(!host){try{const rows=await recentTrades();if(g!==epoch)return;total+=mergeOlderTrades(rows)}catch(e){error=e.message||error}return}
for(let done=1;done<pages&&trades.length<180000;){if(g!==epoch)return;if(targetMinutes>0&&trades.at(-1).t-trades[0].t>=targetMinutes*60000)break;await new Promise(resolve=>setTimeout(resolve,4000));if(g!==epoch)return;edge=trades[0].id;const count=Math.min(2,pages-done,Math.ceil(edge/1000),Math.max(0,Math.floor((180000-trades.length)/1000)));if(!count)break;$('tradeHistoryState').textContent='Loading trades… '+num(total)+' / up to '+num(pages*1000)+' · '+Math.floor((trades.at(-1).t-trades[0].t)/60000)+'m covered';const requests=Array.from({length:count},(_,i)=>fetchTradePage(host,Math.max(0,edge-(i+1)*1000)));const results=await Promise.allSettled(requests);if(g!==epoch)return;const blocked=results.find(x=>x.status==='rejected'&&(x.reason?.status===429||x.reason?.status===418));if(blocked)throw blocked.reason;const n=mergeOlderTrades(results.flatMap(x=>x.status==='fulfilled'?x.value:[]));total+=n;done+=count;if(n<count*1000)break}
}catch(e){error=e.message||'Request failed'}finally{if(g===epoch){tradeLoading=false;$('moreTrades').disabled=trades.length>=180000;tradeCoverage();if(!total)$('tradeHistoryState').textContent='Older trades unavailable · '+(error||'no earlier records');else $('tradeHistoryState').textContent+=' · '+num(total)+' backfilled';dirty=true}}}
