function hyperCandle(x,p){if(!x||x.s!==symbol||x.i!==TF[p])return null;const v=window.ZafaMarketData.candle({time:x.t,end:x.T,open:x.o,high:x.h,low:x.l,close:x.c,volume:x.v});if(!v)return null;return {t:v.t,o:v.o/TICK,h:v.h/TICK,l:v.l/TICK,c:v.c/TICK,vol:v.v,quote:NaN,buy:NaN,n:Number(x.n),closed:v.end<Date.now(),event:Math.min(Date.now(),v.end)}}
function rebuildHyper(){hlNeedsRebuild=false;const m=new Map(),native=nativeMap(),step=period*60000;for(const k of native.values()){const b=newBar(k.t,k.o);b.history=true;b.high=k.h;b.low=k.l;b.close=k.c;m.set(k.t,b)}for(const t of trades){const ts=barTime(t.t);let b=m.get(ts);if(!b){b=newBar(ts,t.p);m.set(ts,b)}b.history=false;b.partial=true;b.high=Math.max(b.high,t.p);b.low=Math.min(b.low,t.p);if(!native.has(ts))b.close=t.p;if(t.side==='buy')b.buy+=t.q;else b.sell+=t.q;add(b.levels,bucket(t.p),t.side==='buy'?t.q:0,t.side==='sell'?t.q:0);(b.raw??=[]).push(t)}const sorted=[...m.values()].sort((a,b)=>a.time-b.time);bars=[];for(const b of sorted){const prev=bars.at(-1);if(prev&&b.time-prev.time>step&&b.time-prev.time<=step*600){for(let t=prev.time+step;t<b.time;t+=step){const gap=newBar(t,prev.close);gap.empty=true;gap.history=true;bars.push(gap)}}else if(prev&&b.time-prev.time>step*600){bars=[]}b.poc=poc(b.levels);for(const t of b.raw||[])t.bar=bars.length;bars.push(b)}BASE=bars[0]?.time??0;if(trades.length&&trades[0].t<BASE)trades=trades.filter(t=>t.t>=BASE);cursor=bars.length;tradeCursor=trades.length;dirty=true}
