async function loadCorrelation(){const gen=++corrGeneration,tf=Number($('corrTF').value),end=Math.floor(Date.now()/(tf*60000))*tf*60000,start=Math.max(end-Number($('corrDays').value)*86400000,end-5000*tf*60000);$('corrStatus').textContent='Loading XYZ100…';const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),10000);try{const res=await fetch('https://api.hyperliquid.xyz/info',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'candleSnapshot',req:{coin:'xyz:XYZ100',interval:TF[tf],startTime:start,endTime:end}}),signal:ctl.signal});if(!res.ok)throw Error('HTTP '+res.status);const rows=await res.json();if(gen!==corrGeneration)return;const map=new Map();if(!Array.isArray(rows))throw Error('Invalid response');for(const x of rows){const t=Number(x.t),p=Number(x.c);if(x.s==='xyz:XYZ100'&&x.i===TF[tf]&&Number.isSafeInteger(t)&&t% (tf*60000)===0&&t+tf*60000<=end&&Number.isFinite(p)&&p>0)map.set(t,p)}if(!map.size)throw Error('No matching closed candles');corrData.xyz=map;$('corrStatus').textContent='XYZ100: '+map.size+' closed candles · yellow / NQ blue / US100 green';renderCorr()}catch(e){if(gen===corrGeneration)$('corrStatus').textContent='XYZ100 API unavailable: '+e.message+' · import CSV instead.'}finally{clearTimeout(timer)}}
